def neighbors(world: World, x: int, y: int) -> list[tuple[int, int]]:
    # Orthogonal adjacency gives the garden readable migration patterns.
    return [(a, b) for a, b in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1))
